import{_ as n,o as r,c as t,a2 as a}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Speichern und später fortsetzen","description":"Ausfüllenden erlauben, ein Formular zu unterbrechen und später weiterzumachen.","frontmatter":{"title":"Speichern und später fortsetzen","description":"Ausfüllenden erlauben, ein Formular zu unterbrechen und später weiterzumachen."},"headers":[],"relativePath":"formulare/speichern-und-fortsetzen.md","filePath":"formulare/speichern-und-fortsetzen.md","lastUpdated":1786170655000}'),i={name:"formulare/speichern-und-fortsetzen.md"};function s(l,e,o,d,h,u){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="speichern-und-spater-fortsetzen" tabindex="-1">Speichern und später fortsetzen <a class="header-anchor" href="#speichern-und-spater-fortsetzen" aria-label="Permalink to &quot;Speichern und später fortsetzen&quot;">​</a></h1><p>Mit dieser Funktion können Ausfüllende ein Formular unterbrechen und später an derselben Stelle weitermachen — ohne dass Eingaben verloren gehen.</p><p>Die Beschreibung in der Oberfläche:</p><blockquote><p><strong>Speichern und später fortfahren</strong></p><p><em>Die Befragten können später zurückkehren, dort weitermachen, wo sie aufgehört haben, und das Formular problemlos ausfüllen, ohne dass ihre zuvor eingegebenen Daten verloren gehen.</em></p></blockquote><h2 id="einschalten" tabindex="-1">Einschalten <a class="header-anchor" href="#einschalten" aria-label="Permalink to &quot;Einschalten&quot;">​</a></h2><p>Im Reiter <strong>Mehr</strong> des Formular-Editors: <strong>Speichern um später fortzufahren</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Tarifabhängig</p><p>Die Funktion steht nicht im Einstiegstarif zur Verfügung.</p></div><h2 id="was-ausfullende-sehen" tabindex="-1">Was Ausfüllende sehen <a class="header-anchor" href="#was-ausfullende-sehen" aria-label="Permalink to &quot;Was Ausfüllende sehen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Text</th></tr></thead><tbody><tr><td>Speichern-Schaltfläche</td><td><strong>Später fortfahren</strong></td></tr><tr><td>Bestätigung</td><td><em>Formular wurde gespeichert!</em></td></tr><tr><td>Beim Wiederaufruf</td><td><em>Das Formular wurde gespeichert, aber noch nicht gesendet!</em></td></tr><tr><td>Erklärung dazu</td><td><em>Sie können das Formular später fertig ausfüllen.</em></td></tr><tr><td>Gespeicherte Stände verwerfen</td><td><strong>Alle löschen</strong></td></tr><tr><td>Dialog schließen</td><td><strong>Fertig</strong></td></tr></tbody></table><h2 id="warum-sich-das-lohnt" tabindex="-1">Warum sich das lohnt <a class="header-anchor" href="#warum-sich-das-lohnt" aria-label="Permalink to &quot;Warum sich das lohnt&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Ohne diese Funktion gehen Eingaben verloren</p><p>Ein Formular wird <strong>erst beim Absenden</strong> gespeichert. Schließt jemand den Browser auf Seite 3 von 5, ist alles weg — ohne Warnung.</p><p>Bei allem, was länger als ein paar Minuten dauert, ist diese Funktion deshalb keine Bequemlichkeit, sondern Schutz vor Frust und Abbrüchen.</p></div><p>Besonders sinnvoll bei:</p><ul><li><a href="/formulare/mehrseitige-formulare">mehrseitigen Formularen</a></li><li>Formularen mit vielen Feldern</li><li>Formularen, für die Unterlagen herausgesucht werden müssen</li><li>Formularen, die überwiegend mobil ausgefüllt werden</li></ul><h2 id="wichtige-eigenschaften" tabindex="-1">Wichtige Eigenschaften <a class="header-anchor" href="#wichtige-eigenschaften" aria-label="Permalink to &quot;Wichtige Eigenschaften&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Ein gespeicherter Stand ist noch kein Eintrag</p><p>Solange nicht abgesendet wurde, existiert <strong>kein Eintrag im Grid</strong>. Die Daten liegen zwischengespeichert und sind für Sie nicht sichtbar.</p><p>Ein Flow mit dem Auslöser <em>Eintrag per Formular</em> startet erst beim tatsächlichen Absenden.</p></div><div class="warning custom-block"><p class="custom-block-title">Der Stand hängt am Gerät und Browser</p><p>Wer auf dem Telefon speichert, findet den Stand nicht automatisch auf dem Rechner wieder. Weisen Sie in der Formularbeschreibung darauf hin, wenn das für Ihren Fall relevant ist.</p></div><h2 id="abgrenzung-zu-ahnlichen-funktionen" tabindex="-1">Abgrenzung zu ähnlichen Funktionen <a class="header-anchor" href="#abgrenzung-zu-ahnlichen-funktionen" aria-label="Permalink to &quot;Abgrenzung zu ähnlichen Funktionen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Funktion</th><th>Zweck</th></tr></thead><tbody><tr><td><strong>Speichern um später fortzufahren</strong></td><td>Der Ausfüllende unterbricht und macht selbst weiter</td></tr><tr><td><a href="/formulare/vorausgefuellte-links">Vorausgefüllter Link</a></td><td><strong>Sie</strong> geben Werte vor, bevor jemand ausfüllt</td></tr><tr><td><a href="/formulare/eintraege-bearbeiten">Eintrag per Formular bearbeiten</a></td><td>Ein <strong>bestehender</strong> Eintrag wird geändert</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Für Rückmeldeschleifen den anderen Weg nehmen</p><p>Wollen Sie, dass jemand einen Vorgang später ergänzt und Sie in der Zwischenzeit den Stand sehen, ist <em>Speichern</em> das falsche Werkzeug — die Daten sind für Sie ja unsichtbar.</p><p>Lassen Sie stattdessen den Eintrag sofort anlegen und verschicken Sie über einen <a href="/flows/aktionen">Flow</a> einen vorausgefüllten Formularlink zur Ergänzung.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/formulare/mehrseitige-formulare">Mehrseitige Formulare</a></li><li><a href="/formulare/vorausgefuellte-links">Vorausgefüllte Links</a></li><li><a href="/formulare/formular-erstellen">Formular erstellen</a></li></ul>',21)])])}const m=n(i,[["render",s]]);export{g as __pageData,m as default};
